"""Render docs from real artifacts so numbers are never hand-typed."""
from .features import FEATURE_DESCRIPTIONS, GROUPS, FEATURE_VERSION


def feature_dictionary_md() -> str:
    out = [f"# Feature Dictionary (feature version `{FEATURE_VERSION}`)\n",
           "Generated by `fraudpipe.docs.feature_dictionary_md()` from `fraudpipe/features.py`. "
           "Do not edit by hand.\n"]
    for g, cols in GROUPS.items():
        out += [f"\n## Group `{g}`\n", "| Feature | Definition |", "|---|---|"]
        out += [f"| `{c}` | {FEATURE_DESCRIPTIONS[c]} |" for c in cols]
    out += ["\n## Categorical\n", f"| `txn_type` | {FEATURE_DESCRIPTIONS['txn_type']} |"]
    out += ["\n**Leakage rules:** features use only earlier transactions; fraud labels become usable only "
            "`label_delay_s` after the transaction (default 24 h); the current row's label is never read."]
    return "\n".join(out) + "\n"


def dataset_card_md(meta: dict) -> str:
    p, s = meta["profile"], meta["split"]
    st = s["stats"]
    warn = "" if meta["is_full_benchmark"] else (
        f"> **WARNING:** built with `--max-rows {meta['max_rows']}`. This is a smoke run, NOT the full benchmark.\n\n")
    rows = "\n".join(f"| {k} | {v['rows']:,} | {v['fraud']:,} |" for k, v in p["fraud_by_type"].items())
    return f"""# Dataset Card - {meta['dataset']} (offline benchmark)

{warn}- **Source file:** `{meta['source_file']}` (SHA-256 `{meta['source_sha256']}`)
- **Intended use:** offline model comparison for an academic prototype. NOT evidence of production banking performance.
- **Not the live-demo data:** the live demo uses a separate simulated stream (see simulator docs).
- **Seed:** {meta['seed']} | **Built:** {meta['built_at']} | Python {meta['python']}, pandas {meta['pandas']}

## Size and class balance
- Rows: {p['rows']:,}; fraud rows: {p['fraud_rows']:,} ({p['fraud_rate']:.4%})
- Duplicate rows: {p['duplicate_rows']:,}; missing values: {sum(p['missing_values'].values())}
- Time span: {p['time_span_hours']:.0f} simulated hours

| Type | Rows | Fraud |
|---|---|---|
{rows}

## Split ({s['method']})
| Split | Rows | Fraud | Fraud rate |
|---|---|---|---|
""" + "\n".join(f"| {k} | {v['rows']:,} | {v['fraud']:,} | {v['fraud_rate']:.4%} |" for k, v in st.items()) + f"""

Cut-offs (epoch s): train < {s['train_end_ts']}, val < {s['val_end_ts']}, test after. Preprocessing is fitted on train only.

## Entity structure (matters for behavioral features)
- Unique users (`nameOrig`): {p['unique_users']:,}; share with more than 1 txn: {p['share_users_with_more_than_1_txn']:.2%}; max txns/user: {p['max_txns_per_user']}
- Unique counterparties (`nameDest`): {p['unique_counterparties']:,}; share with more than 1 txn: {p['share_counterparties_with_more_than_1_txn']:.2%}

## Leakage handling
- Dropped columns: {', '.join(meta['dropped_columns'])} (post-transaction balances are generated from the fraud outcome; `isFlaggedFraud` is the output of a rule system).
- Fraud labels enter history features only after a {meta['label_delay_s']/3600:g} h delay.

## Known limitations
- Synthetic (simulator-generated) data derived from one country's mobile-money logs; fraud patterns are simulated.
- No device or location fields, so the `device_geo` feature group cannot be trained on this dataset.
- `step` is a simulated hour; hour-of-day / day-of-week assume an arbitrary calendar alignment.
- Origin accounts rarely repeat, so per-user behavioral features carry little signal here (see entity structure above).
"""
